SINA_SMART["physics1-energetics"] = {"lecture":"physics1-energetics","title":"Energetics: work, potentials and chemical potential","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physics1-energetics:e5","text":"Gravitational Y = gh; electrical V (J/C); chemical µ = µ⁰ + RT ln C.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e7","text":"Electrochemical potential µ̃ = µ + zFV governs ion movement.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e0","text":"Work dW = F·dl·cos α; joule (M·L²·T⁻²).","topic":"Work","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e1","text":"Positive (α < 90°), negative (α > 90°), zero (α = 90°).","topic":"Work","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e2","text":"Fluid: dW = P·dV.","topic":"Work","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e3","text":"W = −ΔE: spontaneous processes lose potential energy.","topic":"Potential energy and potential","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e4","text":"Potential = potential energy per unit quantity.","topic":"Potential energy and potential","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physics1-energetics:e6","text":"Gas: energy nRT ln(P₂/P₁).","topic":"Potential energy and potential","sec":2,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"zyhes1":"a","5vse8y":"a","1omn1pp":"a","na7h0h":"a","1blgz2d":"a","so9ket":"a","l1um6w":"a","1kxn11o":"a","uy92vn":"a","3nbctu":"a","khdepb":"x"},"mapCounts":{"verified":0,"auto":10,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physics1-energetics:e5":{"s":0,"u":["Gravitational Y = gh; electrical V (J/C); chemical µ = µ⁰ + RT ln C.","Energetics defines work , potential energy and the main potentials (gravitational, electrical, chemical, electrochemical) used in the rest of the course."],"dp":[]},"physics1-energetics:e7":{"s":0,"u":["Electrochemical potential µ̃ = µ + zFV governs ion movement.","Movements of matter in the body (blood flow, diffusion, osmosis, ion currents) are driven by differences in potential .","Energetics defines work , potential energy and the main potentials (gravitational, electrical, chemical, electrochemical) used in the rest of the course."],"dp":[{"h":"Why potentials explain transport","t":"Water, solutes and ions all move spontaneously from a region of high potential to one of low potential, like a ball rolling downhill. Diffusion follows the chemical potential, current follows the electrical potential, and ions follow the combined electrochemical potential. Moving anything uphill, as the Na⁺/K⁺ pump does, needs energy from ATP. Source: the lecture's fundamental property of potentials."}]},"physics1-energetics:e0":{"s":1,"u":["Work dW = F·dl·cos α; joule (M·L²·T⁻²).","The work of a constant force along a straight displacement is the scalar product dW = F·dl = F·dl·cos α ; dimension M·L²·T⁻², unit joule ."],"dp":[]},"physics1-energetics:e1":{"s":1,"u":["Positive (α < 90°), negative (α > 90°), zero (α = 90°).","Work is algebraic: positive (0 ≤ α negative / resistive (90° zero (α = 90°).","Convention: W = −ΔE : positive work is done by the system itself (spontaneous, it loses energy); negative work means the system receives energy from outside."],"dp":[]},"physics1-energetics:e2":{"s":1,"u":["Fluid: dW = P·dV.","For a fluid pushed in a pipe: F = P·S, so dW = P·dV ."],"dp":[]},"physics1-energetics:e3":{"s":2,"u":["W = −ΔE: spontaneous processes lose potential energy.","Fundamental property : any spontaneous displacement lowers potential energy (energy is transformed, not lost); any move that raises it is not spontaneous and needs external energy."],"dp":[]},"physics1-energetics:e4":{"s":2,"u":["Potential = potential energy per unit quantity.","The potential difference ΔY = ΔE/X is the energy difference per unit quantity , independent of the amount moved.","The potential energy difference between A and B is the opposite of the work of the force moving a quantity X from A to B: ΔE = −W."],"dp":[]},"physics1-energetics:e6":{"s":2,"u":["Gas: energy nRT ln(P₂/P₁).","Chemical potential of an ideal gas : from dE = −P·dV and PV = nRT, dE = nRT·dP/P, so moving a gas from P₁ to P₂ involves nRT·ln(P₂/P₁); per mole, the chemical potential rises with RT ln P (in a mixture, with the partial pressure; in solution, with concentration: µ = µ⁰ + RT ln C ).","Fundamental property : any spontaneous displacement lowers potential energy (energy is transformed, not lost); any move that raises it is not spontaneous and needs external energy."],"dp":[]}},"meta":{"zyhes1":{"a":"recall","vg":"physics1-energetics:e0/recall/1"},"5vse8y":{"a":"recall","vg":"physics1-energetics:e0/recall/2"},"1omn1pp":{"a":"recall","vg":"physics1-energetics:e0/recall/3"},"na7h0h":{"a":"recall","vg":"physics1-energetics:e2/recall/1"},"1blgz2d":{"a":"recall","vg":"physics1-energetics:e1/recall/1"},"so9ket":{"a":"recall","vg":"physics1-energetics:e4/recall/1"},"l1um6w":{"a":"recall","vg":"physics1-energetics:e3/recall/1"},"1kxn11o":{"a":"recall","vg":"physics1-energetics:e5/recall/1"},"uy92vn":{"a":"recall","vg":"physics1-energetics:e5/recall/2"},"3nbctu":{"a":"recall","vg":"physics1-energetics:e7/recall/1"}},"explRev":"bfac625713a1"};
